async function n(){const e=window.APP_CONFIG?.baseUrl||"/";try{const t=await(await fetch(`${e}api/sports`)).json();return t.success?t.data.map(s=>({id:s.sport_id,name:s.sport_name})):[]}catch(r){return console.error("Fetch Sports Error:",r),[]}}async function c(e=null){const r=window.APP_CONFIG?.baseUrl||"/",t=e?`${r}api/leagues?sport_id=${e}`:`${r}api/leagues`;try{const o=await(await fetch(t)).json();return o.success?o.data.map(a=>({id:a.league_id,name:a.league,sportId:a.sport_id})):[]}catch(s){return console.error("Fetch Leagues Error:",s),[]}}async function i(){const e=window.APP_CONFIG?.baseUrl||"/";try{const t=await(await fetch(`${e}api/sports?status=all`)).json();return t.success?t.data.map(s=>({id:s.sport_id,name:s.sport_name,isActive:s.status_id===1})):[]}catch(r){return console.error("Fetch All Sports Error:",r),[]}}async function u(e=null){const r=window.APP_CONFIG?.baseUrl||"/",t=e?`${r}api/leagues?status=all&sport_id=${e}`:`${r}api/leagues?status=all`;try{const o=await(await fetch(t)).json();return o.success?o.data.map(a=>({id:a.league_id,name:a.league,sportId:a.sport_id,isActive:a.status_id===1})):[]}catch(s){return console.error("Fetch All Leagues Error:",s),[]}}async function l(e=null){const r=window.APP_CONFIG?.baseUrl||"/",t=e?`${r}api/divisions?league_id=${e}`:`${r}api/divisions`;try{const o=await(await fetch(t)).json();return o.success?o.data.map(a=>({id:a.division_id,name:a.division,price:parseFloat(a.price),leagueId:a.league_id})):[]}catch(s){return console.error("Fetch Divisions Error:",s),[]}}async function d(){const e=window.APP_CONFIG?.baseUrl||"/";try{const t=await(await fetch(`${e}api/sources`)).json();return t.success?t.data.map(s=>({id:s.entry_id,name:s.hear_about_us})):[]}catch(r){return console.error("Fetch Sources Error:",r),[]}}export{u as a,n as b,d as c,c as d,l as e,i as f};
